    public int compare(anytype o1, anytype o2)
    {
        GUPPriceEngineJournalLineAggregationObject obj1 = o1;
        GUPPriceEngineJournalLineAggregationObject obj2 = o2;

        // Sort by priority in descending order.
        if (obj1.parmJournalLinePriority() != obj2.parmJournalLinePriority())
        {
            return obj2.parmJournalLinePriority() - obj1.parmJournalLinePriority();
        }

        // Sort by price in ascending order.
        if (obj1.parmLowestPrice() > obj2.parmLowestPrice())
        {
            return 1;
        }
        else if (obj1.parmLowestPrice() < obj2.parmLowestPrice())
        {
            return -1;
        }
        return 0;
    }
